import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] rows = new long[n][2];
        for (int i = 0; i < n; i++) {
            rows[i][0] = nextLong();
            rows[i][1] = nextLong();
        }
        Arrays.sort(rows, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        long left = rows[0][0], right = rows[0][1], total = 0;
        for (int i = 1; i < n; i++) {
            long start = rows[i][0], end = rows[i][1];
            if (start > right) {
                // Disjoint from the current merged block: settle it.
                total += right - left + 1;
                left = start;
                right = end;
            } else {
                right = Math.max(right, end);
            }
        }
        System.out.println(total + right - left + 1);
    }
}

package main

import (
	"cmp"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	rows := make([][2]int64, n)
	for i := range rows {
		rows[i][0] = nextInt()
		rows[i][1] = nextInt()
	}
	slices.SortFunc(rows, func(x, y [2]int64) int {
		if x[0] != y[0] {
			return cmp.Compare(x[0], y[0])
		}
		return cmp.Compare(x[1], y[1])
	})
	left, right, total := rows[0][0], rows[0][1], int64(0)
	for _, r := range rows[1:] {
		if r[0] > right {
			// Disjoint from the current merged block: settle it.
			total += right - left + 1
			left, right = r[0], r[1]
		} else {
			right = max(right, r[1])
		}
	}
	fmt.Println(total + right - left + 1)
}
